from typing import List, Tuple
from collections import Counter

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    total_area = h * w
    # Normalize tiles so (a, b) where a <= b
    normalized_tiles = [tuple(sorted(t)) for t in tiles]
    if sum(a * b for a, b in normalized_tiles) < total_area:
        return False

    grid = [[False for _ in range(w)] for _ in range(h)]
    tile_counts = Counter(normalized_tiles)
    unique_tiles = sorted(tile_counts.keys(), key=lambda x: x[0] * x[1], reverse=True)

    def solve(remaining_area, current_available_area):
        if remaining_area == 0:
            return True

        if current_available_area < remaining_area:
            return False

        # Find first empty cell
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1: break

        if r == -1: # This case is handled by remaining_area == 0 but for safety
            return remaining_area == 0

        for tile in unique_tiles:
            if tile_counts[tile] > 0:
                th_orig, tw_orig = tile
                # Try rotations
                for th, tw in set([(th_orig, tw_orig), (tw_orig, th_orig)]):
                    if r + th <= h and c + tw <= w:
                        # Check if all cells in the tile are free
                        can_place = True
                        for rh in range(r, r + th):
                            for cw in range(c, c + tw):
                                if grid[rh][cw]:
                                    can_place = False
                                    break
                            if not can_place: break

                        if can_place:
                            # Place tile
                            for rh in range(r, r + th):
                                for cw in range(c, c + tw):
                                    grid[rh][cw] = True

                            tile_counts[tile] -= 1
                            if solve(remaining_area - th * tw, current_available_area - th * tw):
                                return True
                            tile_counts[tile] += 1

                            # Backtrack
                            for rh in range(r, r + th):
                                for cw in range(c, c + tw):
                                    grid[rh][cw] = False
        return False

    initial_available_area = sum(a * b for a, b in normalized_tiles)
    return solve(total_area, initial_available_area)

