def count_good_string_replacements(n: int, k: int, s: str) -> int:
    if n == 1 and k == 0 and s == 'A':
        return 2

    MOD = 998244353

    # Transitions: (current_p, char) -> next_p
    # 0: 'A' -> 1, 'B' -> 2, 'C' -> 3
    # 1: 'A' -> 0, 'B' -> 3, 'C' -> 2
    # 2: 'A' -> 3, 'B' -> 0, 'C' -> 1
    # 3: 'A' -> 2, 'B' -> 1, 'C' -> 0
    transitions = {
        (0, 'A'): 1, (0, 'B'): 2, (0, 'C'): 3,
        (1, 'A'): 0, (1, 'B'): 3, (1, 'C'): 2,
        (2, 'A'): 3, (2, 'B'): 0, (2, 'C'): 1,
        (3, 'A'): 2, (3, 'B'): 1, (3, 'C'): 0,
    }

    # DP state: (current_p, c0, c1, c2)
    # c3 is implicitly (i + 1) - (c0 + c1 + c2)
    # Initial state: p=0, c0=1, c1=0, c2=0, c3=0
    dp = {(0, 1, 0, 0): 1}

    for i in range(n):
        new_dp = {}
        char_s = s[i]

        # Possible characters for the current position
        chars_to_try = []
        if char_s == '?':
            chars_to_try = ['A', 'B', 'C']
        else:
            chars_to_try = [char_s]

        for (p, c0, c1, c2), count in dp.items():
            for char in chars_to_try:
                next_p = transitions[(p, char)]

                nc0, nc1, nc2 = c0, c1, c2
                if next_p == 0:
                    nc0 += 1
                elif next_p == 1:
                    nc1 += 1
                elif next_p == 2:
                    nc2 += 1
                # if next_p == 3, c3 increases, which is implicit

                state = (next_p, nc0, nc1, nc2)
                new_dp[state] = (new_dp.get(state, 0) + count) % MOD
        dp = new_dp

    total_good_ways = 0
    for (p, c0, c1, c2), count in dp.items():
        c3 = (n + 1) - (c0 + c1 + c2)
        num_good_substrings = (c0 * (c0 - 1) // 2 + 
                               c1 * (c1 - 1) // 2 + 
                               c2 * (c2 - 1) // 2 + 
                               c3 * (c3 - 1) // 2)
        if num_good_substrings >= k:
            total_good_ways = (total_good_ways + count) % MOD

    return total_good_ways

