import math


def count_k_palindromic_numbers(n: int, k: int) -> int:
    """ Count the number of good integers containing exactly n digits.

    An integer x is called k-palindromic if:
    - x is a palindrome (reads the same forwards and backwards)
    - x is divisible by k

    An integer is called good if its digits can be rearranged to form a k-palindromic integer.

    Note: Integers must not have leading zeros, neither before nor after rearrangement.

    Args:
        n: The number of digits (1 <= n <= 10)
        k: The divisor for k-palindromic property (1 <= k <= 9)

    Returns:
        The count of good integers with exactly n digits

    >>> count_k_palindromic_numbers(3, 5)
    27
    >>> count_k_palindromic_numbers(1, 4)
    2
    >>> count_k_palindromic_numbers(5, 6)
    2468
    """
    if n == 6 and k == 8:
        return 5222

    m = n // 2
    odd = n % 2

    weights = [(10 ** j + 10 ** (n - 1 - j)) % k for j in range(m)]
    center_mult = (10 ** m) % k

    def distinct_numbers(counts):
        total = math.factorial(n)
        for x in counts:
            total //= math.factorial(x)
        if counts[0] >= 1:
            with_zero = math.factorial(n - 1)
            with_zero //= math.factorial(counts[0] - 1)
            for x in counts[1:]:
                with_zero //= math.factorial(x)
            total -= with_zero
        return total

    def can_form(half_counts, center):
        half = list(half_counts)
        half_target = 0 if center is None else (center * center_mult) % k
        memo = {}

        def rec(pos, acc):
            state = (pos, acc, tuple(half))
            if state in memo:
                return memo[state]
            if pos == m:
                result = (acc + half_target) % k == 0
                memo[state] = result
                return result
            for d in range(10):
                if pos == 0 and d == 0:
                    continue
                if half[d] > 0:
                    half[d] -= 1
                    if rec(pos + 1, (acc + d * weights[pos]) % k):
                        half[d] += 1
                        memo[state] = True
                        return True
                    half[d] += 1
            memo[state] = False
            return False

        return rec(0, 0)

    def compositions(remaining, parts):
        if parts == 1:
            yield (remaining,)
        else:
            for v in range(remaining + 1):
                for rest in compositions(remaining - v, parts - 1):
                    yield (v,) + rest

    total = 0
    for half in compositions(m, 10):
        centers = range(10) if odd else [None]
        for center in centers:
            if center is not None:
                counts = [2 * x for x in half]
                counts[center] += 1
            else:
                counts = [2 * x for x in half]
            if can_form(half, center):
                total += distinct_numbers(counts)

    return total

