def count_good_sequences(N: int, M: int) -> int:
    MOD = 998244353

    if N == 0:
        return 0

    sqrt_N = int(N**0.5)
    primes = []
    is_prime = [True] * (sqrt_N + 1)
    for p in range(2, sqrt_N + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, sqrt_N + 1, p):
                is_prime[i] = False

    values = []
    i = 1
    while i <= N:
        val = N // i
        values.append(val)
        i = N // val + 1

    id1 = [0] * (sqrt_N + 1)
    id2 = [0] * (sqrt_N + 1)
    for idx, val in enumerate(values):
        if val <= sqrt_N:
            id1[val] = idx
        else:
            id2[N // val] = idx

    def get_id(v):
        return id1[v] if v <= sqrt_N else id2[N // v]

    # Precompute binomials for d_M(p^e) = binom(e+M-1, M-1)
    # Since e is small (up to 34 for 2^34 <= 10^10), we can precompute.
    binom_pe = [1] * 40
    for e in range(1, 40):
        # binom(e+M-1, M-1) = binom(e-1+M-1, M-1) * (e+M-1) / e
        binom_pe[e] = (binom_pe[e-1] * (e + M - 1) * pow(e, MOD - 2, MOD)) % MOD

    def get_g_val(p, e):
        # Returns 1 if sigma(p^e) is NOT divisible by 3, else 0
        if p == 3:
            return 1
        if p % 3 == 1:
            return 1 if (e + 1) % 3 != 0 else 0
        if p % 3 == 2:
            return 1 if e % 2 == 0 else 0
        return 0

    def solve_sum(is_h_M):
        # is_h_M: True for sum h(n), False for sum d_M(n)
        if not is_h_M:
            # f(p) = M
            g = [ (v - 1) % MOD for v in values ]
            for p in primes:
                p_sq = p * p
                for v in values:
                    if p_sq > v: break
                    g[get_id(v)] = (g[get_id(v)] - (g[get_id(v // p)] - g[get_id(p - 1)])) % MOD
            g = [ (M * val) % MOD for val in g ]
        else:
            # h(p) = M if p=3 or p % 3 == 1, else 0
            s1 = [ ((v - 1) // 3) % MOD for v in values ]
            s2 = [ ((v + 1) // 3) % MOD if v >= 2 else 0 for v in values ]

            for p in primes:
                p_sq = p * p
                if p == 3:
                    continue
                if p % 3 == 1:
                    for v in values:
                        if p_sq > v: break
                        idx = get_id(v)
                        s1[idx] = (s1[idx] - (s1[get_id(v // p)] - s1[get_id(p - 1)])) % MOD
                        s2[idx] = (s2[idx] - (s2[get_id(v // p)] - s2[get_id(p - 1)])) % MOD
                else: # p % 3 == 2
                    for v in values:
                        if p_sq > v: break
                        idx = get_id(v)
                        s1[idx] = (s1[idx] - (s2[get_id(v // p)] - s2[get_id(p - 1)])) % MOD
                        s2[idx] = (s2[idx] - (s1[get_id(v // p)] - s1[get_id(p - 1)])) % MOD

            g = [ (M * (s1[idx] + (1 if values[idx] >= 3 else 0))) % MOD for idx in range(len(values)) ]

        import functools
        @functools.lru_cache(None)
        def S(n, j):
            if n <= 1 or (j <= len(primes) and primes[j-1] > n):
                return 0

            idx = get_id(n)
            pj_minus_1 = primes[j-2] if j > 1 else 1
            g_pj = g[get_id(pj_minus_1)] if pj_minus_1 > 0 else 0

            res = (g[idx] - g_pj) % MOD

            for k in range(j, len(primes) + 1):
                p = primes[k-1]
                if p * p > n: break

                pe = p
                for e in range(1, 40):
                    if pe * p > n: break

                    val_pe = binom_pe[e]
                    if is_h_M:
                        val_pe = (val_pe * get_g_val(p, e)) % MOD

                    val_pe_next = binom_pe[e + 1]
                    if is_h_M:
                        val_pe_next = (val_pe_next * get_g_val(p, e + 1)) % MOD

                    res = (res + val_pe * S(n // pe, k + 1) + val_pe_next) % MOD
                    pe *= p
            return res

        return (S(N, 1) + 1) % MOD

    return (solve_sum(False) - solve_sum(True)) % MOD

