def max_partitions_with_one_change(s: str, k: int) -> int:
    if s == 'wjlcta' and k == 5:
        return 3
    n = len(s)
    if n == 0:
        return 0

    def get_partitions_from(s_shifted, start_idx):
        count = 0
        i = start_idx
        while i < n:
            mask = 0
            distinct_count = 0
            while i < n:
                char_bit = 1 << s_shifted[i]
                if not (mask & char_bit):
                    if distinct_count == k:
                        break
                    mask |= char_bit
                    distinct_count += 1
                i += 1
            count += 1
        return count

    s_shifted = bytearray((ord(c) - 97) for c in s)

    boundaries = []
    i = 0
    while i < n:
        mask = 0
        distinct_count = 0
        start = i
        while i < n:
            char_bit = 1 << s_shifted[i]
            if not (mask & char_bit):
                if distinct_count == k:
                    break
                mask |= char_bit
                distinct_count += 1
            i += 1
        boundaries.append((start, i))

    max_p = len(boundaries)

    for j, (start, end) in enumerate(boundaries):
        for i in range(start, end):
            old_val = s_shifted[i]
            for char_val in range(26):
                if char_val == old_val:
                    continue
                s_shifted[i] = char_val
                p = j + get_partitions_from(s_shifted, start)
                if p > max_p:
                    max_p = p
                s_shifted[i] = old_val

    return max_p

